"use client";

import { useState, useCallback } from "react";
import { Upload, FileType, FileWarning } from "lucide-react";
import { Button } from "@/components/ui/button";

interface UploadDropzoneProps {
  onUpload?: (files: FileList | null) => void;
  accept?: string;
  maxSizeMB?: number;
  multiple?: boolean;
}

export function UploadDropzone({ 
  onUpload, 
  accept = ".pdf,.jpg,.png", 
  maxSizeMB = 10,
  multiple = false
}: UploadDropzoneProps) {
  const [isDragging, setIsDragging] = useState(false);

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  }, []);

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (onUpload && e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      onUpload(e.dataTransfer.files);
    }
  }, [onUpload]);

  const handleFileChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    if (onUpload && e.target.files && e.target.files.length > 0) {
      onUpload(e.target.files);
    }
  }, [onUpload]);

  return (
    <div 
      className={`relative w-full max-w-3xl mx-auto rounded-2xl border-2 border-dashed transition-all duration-200 p-12 text-center 
        ${isDragging ? 'border-primary bg-primary/5' : 'border-border hover:border-primary/50 hover:bg-secondary/50 bg-background'}`}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
    >
      <input 
        type="file" 
        className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
        accept={accept}
        multiple={multiple}
        onChange={handleFileChange}
        aria-label="Upload file"
      />
      
      <div className="flex flex-col items-center justify-center space-y-4 pointer-events-none">
        <div className={`p-4 rounded-full transition-colors duration-200 ${isDragging ? 'bg-primary text-primary-foreground' : 'bg-secondary text-primary'}`}>
          <Upload className="w-8 h-8" strokeWidth={2} />
        </div>
        
        <div className="space-y-1">
          <h3 className="text-xl font-semibold text-foreground">
            {isDragging ? 'Drop your files here' : 'Choose a file or drag & drop it here'}
          </h3>
          <p className="text-muted-foreground text-sm max-w-sm mx-auto">
            Supported formats: {accept.split(',').join(', ')}. Maximum file size: {maxSizeMB}MB.
          </p>
        </div>
        
        <Button size="lg" className="pointer-events-auto mt-4 px-8 rounded-full font-medium shadow-sm">
          Browse Files
        </Button>
      </div>
    </div>
  );
}
